SELECT u.id, u.username FROM app_user u JOIN workspace_member wm ON wm.user_id = u.id AND wm.workspace_id = #{workspaceId} AND wm.status = 'active' WHERE u.id IN
#{id}
ORDER BY u.id

SELECT u.id FROM app_user u JOIN workspace_member wm ON wm.user_id = u.id WHERE wm.workspace_id = #{workspaceId} AND wm.status IN ('active', 'pending') AND (u.username LIKE #{query} OR u.display_name LIKE #{query}) AND u.id IN
#{id}
ORDER BY u.id

