mapper.update:
UPDATE app_user
username = #{username}, display_name = #{displayName}, timezone = COALESCE(#{timezone}, timezone),
WHERE id = #{id}

UPDATE app_user
SET last_login_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE app_user
SET epoch_restamp_session_primary_id = #{sessionPrimaryId},
    epoch_restamp_epoch = #{epoch}
WHERE id = #{id}

UPDATE app_user
SET password_hash = #{passwordHash}
WHERE id = #{id}

UPDATE app_user
SET email = #{email}
WHERE id = #{id}

UPDATE app_user
SET email_verified = TRUE
WHERE id = #{id}

UPDATE app_user
SET profile_picture_url = #{profilePictureUrl}
WHERE id = #{id} AND profile_picture_url <=> #{currentProfilePictureUrl}

UPDATE app_user
SET timezone = #{timezone}
WHERE id = #{id}

UPDATE app_user
SET locale = #{locale}
WHERE id = #{id}
